(function registerClarkConcourseFloorData() {
  const group = 'Concourse Floor & Block Out';
  if (Array.isArray(window.CLARK_WORK_GROUPS) && !window.CLARK_WORK_GROUPS.includes(group)) {
    const futureIndex = window.CLARK_WORK_GROUPS.indexOf('Future / Other');
    if (futureIndex >= 0) window.CLARK_WORK_GROUPS.splice(futureIndex, 0, group);
    else window.CLARK_WORK_GROUPS.push(group);
  }
  if (!Array.isArray(window.CLARK_STATION_POINTS)) window.CLARK_STATION_POINTS = [];
  const existing = new Set(window.CLARK_STATION_POINTS.map(p => p.pt));
  (window.CLARK_CONCOURSE_FLOOR_POINTS || []).forEach(point => {
    if (!existing.has(point.pt)) window.CLARK_STATION_POINTS.push(point);
  });
})();
